use serde_json::{json,Value};use std::{fs,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";const P:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175/codegen";
fn main(){let data:Value=serde_json::from_slice(&fs::read(format!("{R}/differences.json")).unwrap()).unwrap();let row=data["different_common_functions"].as_array().unwrap().iter().find(|v|v["name"]=="zopro_core::msm_affine::grouping::scalar_groups").unwrap();let mut rows=vec![];let start=0x217870u64;
for offset in row["differing_byte_offsets"].as_array().unwrap(){let offset=offset.as_u64().unwrap();let mut instructions=BTreeMap::new();for v in["accepted","OFF"]{let asm=fs::read_to_string(format!("{P}/{v}-grouping-0.asm")).unwrap();let mut last=None;for l in asm.lines(){let Some((address,instruction))=l.trim().split_once(':')else{continue};let Ok(address)=u64::from_str_radix(address,16)else{continue};if address>start+offset{break;}last=Some(json!({"address":format!("0x{address:x}"),"instruction":instruction.trim()}));}instructions.insert(v,last.unwrap());}rows.push(json!({"offset":offset,"instructions":instructions}));}
fs::write(format!("{R}/grouping-byte-differences.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();for row in rows{println!("{} A={} OFF={}",row["offset"],row["instructions"]["accepted"]["instruction"],row["instructions"]["OFF"]["instruction"]);}}
